bounded_host_request.command:
set -eu
root=/home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot
cd "$root"
echo ROOT_HEAD=$(git rev-parse HEAD)
echo ROOT_BRANCH=$(git branch --show-current)
echo GAYBBS_RUNNING=$(docker inspect deploy-gaybbs-1 --format '{{.State.Running}}')
echo GAYBBS_RESTARTS=$(docker inspect deploy-gaybbs-1 --format '{{.RestartCount}}')
live=$(docker inspect deploy-gaybbs-1 --format '{{.Image}}')
target=$(docker image inspect gace-tgtumbler-gaybbs:applicant-live-48134d4 --format '{{.Id}}')
test "$live" = "$target" && echo APPLICANT_IMAGE=PASS || echo APPLICANT_IMAGE=FAIL
docker inspect deploy-gaybbs-1 --format '{{range .Config.Env}}{{println .}}{{end}}' | grep '^GAYBBS_NOTIFICATION_DELIVERY_ENABLED=' || :
docker logs --since 60m deploy-gaybbs-1 2>&1 | grep -E 'GAYBBS_BOT_READY|APPLICATION|notification' | tail -n 12 | sed -E 's/[0-9]{8,}/[ID]/g' || :
echo CHECK_DONE
